set -e
SES=session_2026-10-30-ramp-spec-pages-rebuild
D=scratchpad/$SES
for spec in "REF-01034:--field volume --field issue" "REF-01035:--field volume --field issue" "REF-01036:--field volume"; do r=${spec%%:*}; f=${spec#*:}; python3 scripts/db.py correct-source --ref-id $r $f --log-session "$SES" --session "$SES" >/dev/null && echo corrected $r; done
python3 scripts/db.py amend-source --ref-id REF-01033 --field verification_note --replacement "AUTHOR FORM: the Crossref record persisted in retrieval-log/$SES carries each author's given name inside the family-name field ('Hashizume Tsutomu'). Stored as family name plus given-name initial in the payload's order (Japanese names, family name first); verify-authors reports this as a disagreement of form, not of persons. The abstract is in both the Crossref record and the PubMed record (26294512, persisted); no full text was read." --reason "records why the stored author list differs in form from the payload" --session "$SES" >/dev/null && echo note1033
python3 scripts/db.py amend-source --ref-id REF-01034 --field verification_note --replacement "AUTHOR FORM: the Crossref record persisted in retrieval-log/$SES lists institutional affiliations (University at Buffalo; New Jersey Veterans Memorial Home) as author entries between the six persons. Stored here: the six persons only, in the payload's order. The landing page (also persisted) cites 'Lenker, James A., et al.'. Abstract read from the landing page; the open-access PDF link returned a 5.6 kB stub, so no full text was read." --reason "records why the stored author list differs from the payload, and the reading's limit" --session "$SES" >/dev/null && echo note1034
python3 scripts/db.py amend-source --ref-id REF-00139 --field verification_note --replacement "IDENTITY HISTORY: this ref_id has worn three identities. (1) a 2016 reference in the migration review (references/audits/migration-review-2026-05-11.csv, line 140; sessions/session_2026-05-20-ato-rehab.md line 1978); (2) the pre-reset record 'Code on Accessibility 2025 Chapter 8 - wayfinding' (source_locators, REFERENCE-ONLY, the same URL); (3) here, the whole Code on Accessibility in the Built Environment 2025, v1.1 (1 March 2026), admitted under the stash id because the stash holds this URL against it (research_batch_dod R9a). The stash row's title names Chapter 8 only; the document at that URL is the whole Code." --reason "R9a asks for the held id to be reused; the row must say what the id has meant" --session "$SES" >/dev/null && echo note139
for r in REF-01033 REF-01034 REF-01035 REF-01036; do python3 scripts/db.py amend-source --ref-id $r --field doi_resolution_outcome --replacement RESOLVED --reason "the DOI's Crossref work record was retrieved (HTTP 200) and persisted in retrieval-log/$SES; title, year and container agree with the stored row" --session "$SES" >/dev/null && echo resolved $r; done
python3 scripts/db.py update-code-lead --lead-id 56 --append-note "[2026-10-30] RETRIEVED: the BCA Code, 2025 edition (v1.1, 1 March 2026), was fetched from file.go.gov.sg/bca-coa2025.pdf and admitted as REF-00139; this lead names the 2019 edition, which the 2025 Code supersedes. Values are on the extractions of REF-00139, not here." --status RETRIEVED --session "$SES" >/dev/null && echo lead56
